request.description:
Returns all participants for a reservation.
Permission: sales.reservations.view
Expected: 200 OK with data[] of {id, user_id, user:{id,name}, did_bring, did_convince, did_close, weight, notes}

body.raw:
{
  "participants": [
    {
      "user_id": {{sales_user_id}},
      "did_bring": true,
      "did_convince": true,
      "did_close": false,
      "weight": 2.0,
      "notes": "Updated — also convinced client"
    },
    {
      "user_id": {{participant_user_id}},
      "did_bring": false,
      "did_convince": false,
      "did_close": true,
      "weight": 1.0,
      "notes": null
    }
  ]
}

request.description:
Returns paginated list of project commission settings.
Permission: accounting.sold-units.view OR accounting.sold-units.manage

Response shape: {success, data[], meta:{current_page, last_page, per_page, total}}

item.description:
Requests that are expected to return 422 validation errors.
Useful for verifying safeguard behavior.

All return: {success: false, message: string, errors: {field: [message]}}
